CREATE TABLE IF NOT EXISTS guest_identities(id uuid PRIMARY KEY, auth_secret_hash text NOT NULL UNIQUE, nickname text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS rooms(id uuid PRIMARY KEY, owner_member_id text NOT NULL, planned_players integer NOT NULL CHECK(planned_players BETWEEN 1 AND 6), content_version text NOT NULL, phase text NOT NULL, code_digest text NOT NULL UNIQUE, writer_id uuid, writer_epoch bigint NOT NULL DEFAULT 0 CHECK(writer_epoch>=0), lease_until timestamptz, durable_version bigint NOT NULL DEFAULT 0 CHECK(durable_version>=0), durable_sim_tick bigint NOT NULL DEFAULT 0 CHECK(durable_sim_tick>=0), head_hash text NOT NULL, latest_snapshot_version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS room_members(id text NOT NULL, room_id uuid REFERENCES rooms(id) ON DELETE CASCADE, guest_id uuid REFERENCES guest_identities(id), controller_epoch integer NOT NULL CHECK(controller_epoch>=0), seat_reserved_until timestamptz, PRIMARY KEY(room_id,id), UNIQUE(room_id,guest_id));
CREATE TABLE IF NOT EXISTS room_event_batches(room_id uuid REFERENCES rooms(id) ON DELETE CASCADE,durable_version bigint NOT NULL,commit_id uuid NOT NULL,writer_epoch bigint NOT NULL,from_version bigint NOT NULL,from_tick bigint NOT NULL,to_tick bigint NOT NULL,delta jsonb NOT NULL,before_hash text NOT NULL,after_hash text NOT NULL,committed_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(room_id,durable_version),UNIQUE(room_id,commit_id));
CREATE TABLE IF NOT EXISTS command_receipts(room_id uuid REFERENCES rooms(id) ON DELETE CASCADE,member_id text NOT NULL,command_id uuid NOT NULL,payload_hash text NOT NULL,status text NOT NULL,durable_version bigint NOT NULL,outcome jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(room_id,member_id,command_id));
CREATE TABLE IF NOT EXISTS room_snapshots(room_id uuid REFERENCES rooms(id) ON DELETE CASCADE,durable_version bigint NOT NULL,schema_version integer NOT NULL,content_version text NOT NULL,sim_tick bigint NOT NULL,state_blob jsonb NOT NULL,state_hash text NOT NULL,verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(room_id,durable_version));
CREATE TABLE IF NOT EXISTS owner_recovery_keys(room_id uuid PRIMARY KEY REFERENCES rooms(id) ON DELETE CASCADE,key_hash text NOT NULL,key_generation integer NOT NULL DEFAULT 1,rotated_at timestamptz NOT NULL DEFAULT clock_timestamp());
